function buildBazi48PagePlan() {
  const pages = [];
  const add = (p) => pages.push({ ...p, pageNumber: pages.length + 1 });
  ["COVER", "METHOD_INTRO", "ORIGIN", "PHIOS_LENS", "HOW_TO_READ"].forEach((role, i) => add({ role, staticAssetPage: i + 1 }));
  add({ role: "OVERVIEW" });
  for (let i = 0; i < 3; i++) add({ role: "TECHNICAL_FOUNDATION", diagramId: DIAGRAM_PLAN[i].id });
  add({ role: "TECHNICAL_FOUNDATION", diagramIds: ["D04", "D05"] });
  SECTIONS.forEach((s, i) => {
    add({ role: "SECTION_OPENER", sectionId: s.sectionId });
    add({ role: "SECTION_DIAGRAM", sectionId: s.sectionId, diagramId: DIAGRAM_PLAN[i + 5].id });
    add({ role: "INTERPRETATION_A", sectionId: s.sectionId, excerptIndex: 0 });
    add({ role: "INTERPRETATION_B", sectionId: s.sectionId, excerptIndex: 1 });
  });
  add({ role: "INTEGRATED_MAP", diagramId: "D15" });
  add({ role: "CLOSING_REALITY_BRIDGE" });
  return pages;
}
